-- P06 PREONLY.  Do not apply or journal without independent critical approval.
-- P05 v1.2 now supplies this composite key; retain the idempotent assertion
-- for older PRE fixtures without colliding with the applied prerequisite.
CREATE UNIQUE INDEX IF NOT EXISTS guide_run_artifacts_workspace_row_unique ON guide_run_artifacts(workspace_id,id);
CREATE TABLE guide_run_action_bindings (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE cascade,
 run_id uuid NOT NULL, guide_revision_id uuid NOT NULL, disposition_artifact_id uuid NOT NULL, action_unit_id uuid NOT NULL, proposal_bundle_id uuid NOT NULL,
 action_unit_ref text NOT NULL, action_unit_hash text NOT NULL, proposal_ref text NOT NULL, proposal_hash text NOT NULL,
  entity_ref text NOT NULL, member_ref text NOT NULL, membership_hash text NOT NULL, slice_ref text NOT NULL, market_key text NOT NULL, effective_guide_set_hash text NOT NULL, resolution_hash text NOT NULL, decision text NOT NULL DEFAULT 'pending', version text NOT NULL DEFAULT 'p06-action-binding/1.0.0', created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT guide_run_action_bindings_contract CHECK (action_unit_ref ~ '^action_unit_[a-f0-9]{20}$' AND proposal_ref ~ '^action_bundle_[a-f0-9]{20}$' AND action_unit_hash ~ '^[a-f0-9]{64}$' AND proposal_hash ~ '^[a-f0-9]{64}$' AND entity_ref ~ '^[a-z][a-z0-9]{0,31}_[a-z0-9][a-z0-9_.:-]{0,126}$' AND member_ref ~ '^[a-z][a-z0-9]{0,31}_[a-z0-9][a-z0-9_.:-]{0,126}$' AND membership_hash ~ '^[a-f0-9]{64}$' AND slice_ref ~ '^slice_[a-z0-9][a-z0-9_.:-]{0,190}$' AND market_key IN ('yerli','yabanci') AND effective_guide_set_hash ~ '^[a-f0-9]{64}$' AND resolution_hash ~ '^[a-f0-9]{64}$' AND decision='pending' AND version='p06-action-binding/1.0.0')
);
CREATE UNIQUE INDEX guide_run_action_bindings_workspace_row_unique ON guide_run_action_bindings(workspace_id,id);
CREATE UNIQUE INDEX guide_run_action_bindings_workspace_artifact_unique ON guide_run_action_bindings(workspace_id,disposition_artifact_id);
CREATE UNIQUE INDEX guide_run_action_bindings_workspace_unit_unique ON guide_run_action_bindings(workspace_id,run_id,action_unit_id);
CREATE UNIQUE INDEX guide_run_action_bindings_workspace_action_unit_unique ON guide_run_action_bindings(workspace_id,action_unit_id);
CREATE INDEX guide_run_action_bindings_workspace_revision_idx ON guide_run_action_bindings(workspace_id,guide_revision_id);
CREATE INDEX guide_run_action_bindings_workspace_member_idx ON guide_run_action_bindings(workspace_id,member_ref,membership_hash);
CREATE INDEX guide_run_action_bindings_workspace_proposal_idx ON guide_run_action_bindings(workspace_id,proposal_bundle_id);
CREATE INDEX guide_run_action_bindings_workspace_unit_fk_idx ON guide_run_action_bindings(workspace_id,action_unit_id);
CREATE INDEX guide_run_action_bindings_workspace_proposal_fk_idx ON guide_run_action_bindings(workspace_id,proposal_bundle_id);
ALTER TABLE guide_run_action_bindings ADD CONSTRAINT guide_run_action_bindings_run_revision_fk FOREIGN KEY(workspace_id,run_id,guide_revision_id) REFERENCES guide_runs(workspace_id,id,guide_revision_id) ON DELETE cascade;
ALTER TABLE guide_run_action_bindings ADD CONSTRAINT guide_run_action_bindings_disposition_fk FOREIGN KEY(workspace_id,disposition_artifact_id) REFERENCES guide_run_artifacts(workspace_id,id) ON DELETE restrict;
ALTER TABLE guide_run_action_bindings ADD CONSTRAINT guide_run_action_bindings_unit_fk FOREIGN KEY(workspace_id,action_unit_id) REFERENCES action_proposal_units(workspace_id,id) ON DELETE restrict;
ALTER TABLE guide_run_action_bindings ADD CONSTRAINT guide_run_action_bindings_proposal_fk FOREIGN KEY(workspace_id,proposal_bundle_id) REFERENCES action_proposal_bundles(workspace_id,id) ON DELETE restrict;
CREATE OR REPLACE FUNCTION public.guide_run_action_binding_guard() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$ DECLARE ws public.workspaces%ROWTYPE; a public.guide_run_artifacts%ROWTYPE; h public.guide_run_heads%ROWTYPE; r public.guide_runs%ROWTYPE; gr public.guide_revisions%ROWTYPE; g public.guides%ROWTYPE; gh public.guide_heads%ROWTYPE; u public.action_proposal_units%ROWTYPE; b public.action_proposal_bundles%ROWTYPE; candidate jsonb; BEGIN
 IF TG_OP='DELETE' AND EXISTS(SELECT 1 FROM public.workspaces WHERE id=OLD.workspace_id AND lifecycle_state='tombstoning') THEN RETURN OLD; END IF;
 IF TG_OP='INSERT' THEN
  SELECT * INTO ws FROM public.workspaces WHERE id=NEW.workspace_id FOR SHARE; SELECT * INTO a FROM public.guide_run_artifacts WHERE workspace_id=NEW.workspace_id AND id=NEW.disposition_artifact_id FOR SHARE; SELECT * INTO r FROM public.guide_runs WHERE workspace_id=NEW.workspace_id AND id=NEW.run_id AND guide_revision_id=NEW.guide_revision_id FOR SHARE; SELECT * INTO h FROM public.guide_run_heads WHERE workspace_id=NEW.workspace_id AND run_id=NEW.run_id FOR SHARE; SELECT * INTO gr FROM public.guide_revisions WHERE workspace_id=NEW.workspace_id AND id=NEW.guide_revision_id FOR SHARE; SELECT * INTO g FROM public.guides WHERE workspace_id=NEW.workspace_id AND id=r.guide_id FOR SHARE; SELECT * INTO gh FROM public.guide_heads WHERE workspace_id=NEW.workspace_id AND guide_id=r.guide_id FOR SHARE; SELECT * INTO u FROM public.action_proposal_units WHERE workspace_id=NEW.workspace_id AND id=NEW.action_unit_id FOR SHARE; SELECT * INTO b FROM public.action_proposal_bundles WHERE workspace_id=NEW.workspace_id AND id=NEW.proposal_bundle_id FOR SHARE;
  IF ws.id IS NULL OR ws.lifecycle_state IS DISTINCT FROM 'active' OR a.id IS NULL OR r.id IS NULL OR h.run_id IS NULL OR gr.id IS NULL OR g.id IS NULL OR gh.guide_id IS NULL OR u.id IS NULL OR b.id IS NULL OR h.state IS DISTINCT FROM 'completed' OR a.run_id IS DISTINCT FROM r.id OR a.kind IS DISTINCT FROM 'disposition' OR g.tombstoned_at IS NOT NULL OR gh.current_active_revision_id IS DISTINCT FROM r.guide_revision_id OR u.bundle_id IS DISTINCT FROM b.id OR u.unit_ref IS DISTINCT FROM NEW.action_unit_ref OR u.unit_hash IS DISTINCT FROM NEW.action_unit_hash OR b.bundle_ref IS DISTINCT FROM NEW.proposal_ref OR b.bundle_hash IS DISTINCT FROM NEW.proposal_hash OR u.entity_ref IS DISTINCT FROM NEW.entity_ref OR gr.slice_ref IS DISTINCT FROM NEW.slice_ref OR gr.market_key IS DISTINCT FROM NEW.market_key OR a.authority IS DISTINCT FROM '{"canMutateGuide":false,"canApprove":false,"canExecute":false,"canWriteMeta":false}'::jsonb OR a.payload_hash IS DISTINCT FROM public.guide_run_sha256(a.payload) OR a.artifact_ref IS DISTINCT FROM 'guide_run_artifact_'||substr(public.guide_run_sha256(jsonb_build_object('runRef',r.run_ref,'kind',a.kind,'payload',a.payload)),1,24) THEN RAISE EXCEPTION 'P06 action binding source identity invalid'; END IF;
  IF jsonb_typeof(a.payload) IS DISTINCT FROM 'object' OR cardinality(ARRAY(SELECT jsonb_object_keys(a.payload)))<>6 OR NOT (a.payload ?& ARRAY['disposition','trusted','analysisOutcome','guideRevisionHash','mode','actionAllowlist']) OR jsonb_typeof(a.payload->'disposition') IS DISTINCT FROM 'object' OR jsonb_typeof(a.payload->'trusted') IS DISTINCT FROM 'object' OR cardinality(ARRAY(SELECT jsonb_object_keys(a.payload->'trusted')))<>2 OR NOT (a.payload->'trusted' ?& ARRAY['dataQuality','evidenceHash']) OR a.payload->'trusted'->>'dataQuality' IS DISTINCT FROM 'ready' OR a.payload->>'guideRevisionHash' IS DISTINCT FROM r.guide_revision_hash OR a.payload->>'mode' IS DISTINCT FROM gr.mode OR NOT (a.payload->'actionAllowlist' ? (a.payload->'disposition'->'candidate'->>'action')) THEN RAISE EXCEPTION 'P06 disposition envelope invalid'; END IF;
  candidate:=a.payload->'disposition'->'candidate'; IF candidate IS NULL OR jsonb_typeof(candidate) IS DISTINCT FROM 'object' OR cardinality(ARRAY(SELECT jsonb_object_keys(candidate)))<>5 OR NOT (candidate ?& ARRAY['candidateRef','candidateHash','action','routing','stageable']) OR jsonb_typeof(candidate->'stageable')<>'object' OR NOT (candidate->'stageable' ?& ARRAY['version','entityRef','entityLevel','membershipHash','sliceRef','market','typedAction']) OR cardinality(ARRAY(SELECT jsonb_object_keys(candidate->'stageable')))<>7 OR candidate->'stageable'->>'version'<>'candidate/1.1' OR candidate->'stageable'->>'entityRef'<>NEW.member_ref OR candidate->'stageable'->>'sliceRef'<>NEW.slice_ref OR candidate->'stageable'->>'market'<>NEW.market_key OR candidate->'stageable'->>'membershipHash'<>NEW.membership_hash OR candidate->'stageable'->>'membershipHash' !~ '^[a-f0-9]{64}$' OR candidate->'stageable'->>'entityLevel'<>'adset' OR jsonb_typeof(candidate->'stageable'->'typedAction')<>'object' OR candidate->>'candidateHash' IS DISTINCT FROM public.guide_run_sha256(jsonb_build_object('candidateRef',candidate->>'candidateRef','action',candidate->>'action','version',candidate->'stageable'->>'version','entityRef',candidate->'stageable'->>'entityRef','entityLevel',candidate->'stageable'->>'entityLevel','membershipHash',candidate->'stageable'->>'membershipHash','sliceRef',candidate->'stageable'->>'sliceRef','market',candidate->'stageable'->>'market','typedAction',candidate->'stageable'->'typedAction')) OR candidate->'stageable'->'typedAction'->>'kind'<>'status_change' OR candidate->'stageable'->'typedAction'->'entity'->>'level'<>'adset' OR candidate->'stageable'->'typedAction'->'entity'->>'ref'<>NEW.member_ref OR candidate->'stageable'->'typedAction'->>'fromStatus' NOT IN ('ACTIVE','PAUSED') OR candidate->'stageable'->'typedAction'->>'toStatus' NOT IN ('ACTIVE','PAUSED') OR (candidate->>'action'='status_pause' AND NOT (candidate->'stageable'->'typedAction'->>'fromStatus'='ACTIVE' AND candidate->'stageable'->'typedAction'->>'toStatus'='PAUSED')) OR (candidate->>'action'='status_activate' AND NOT (candidate->'stageable'->'typedAction'->>'fromStatus'='PAUSED' AND candidate->'stageable'->'typedAction'->>'toStatus'='ACTIVE')) OR NOT EXISTS(SELECT 1 FROM public.guide_run_artifacts ss CROSS JOIN LATERAL jsonb_array_elements(ss.payload->'members') m WHERE ss.workspace_id=NEW.workspace_id AND ss.run_id=NEW.run_id AND ss.kind='scope_snapshot' AND m->>'memberRef'=NEW.member_ref AND m->>'membershipHash'=NEW.membership_hash) OR candidate->>'candidateRef' !~ '^candidate_[a-z0-9][a-z0-9_.:-]{0,126}$' OR candidate->>'candidateHash' !~ '^[a-f0-9]{64}$' OR candidate->>'routing' NOT IN ('human_approval','limited_autonomy_review') OR candidate->>'action' IS DISTINCT FROM u.action_type OR b.plan_ref IS DISTINCT FROM ('guide_candidate_' || (candidate->>'candidateHash')) OR u.action_plan_payload->>'planHash' IS DISTINCT FROM u.source_hash OR candidate->>'action' NOT IN ('status_pause','status_activate') OR a.payload->'disposition'->>'state' IS DISTINCT FROM 'staged' OR a.payload->'disposition'->>'reason' IS DISTINCT FROM 'candidate_ready' OR a.payload->'disposition'->>'recommendationRef' IS NULL OR a.payload->'disposition'->'authority' IS DISTINCT FROM '{"canApprove":false,"canExecute":false,"canWriteMeta":false,"canEnableAutomation":false}'::jsonb THEN RAISE EXCEPTION 'P06 binding requires exact staged candidate'; END IF;
  RETURN NEW;
 END IF;
 RAISE EXCEPTION 'P06 action binding is append-only';
END $$;
CREATE TRIGGER guide_run_action_bindings_append_only BEFORE INSERT OR UPDATE OR DELETE ON guide_run_action_bindings FOR EACH ROW EXECUTE FUNCTION public.guide_run_action_binding_guard();
ALTER TABLE guide_run_action_bindings ENABLE ROW LEVEL SECURITY; ALTER TABLE guide_run_action_bindings FORCE ROW LEVEL SECURITY;
REVOKE ALL PRIVILEGES ON TABLE guide_run_action_bindings FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL PRIVILEGES ON FUNCTION public.guide_run_action_binding_guard() FROM PUBLIC,anon,authenticated,service_role;
